// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 amount, uint8 reverterFail, address actor) public {
        vm.assume(amount > 0 && amount <= address(c).balance + amount);
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        Reverter reverter = new Reverter();
        vm.deal(address(reverter), amount);
        vm.prank(address(reverter));
        (bool s,) = address(c).call{value: amount}("");
        require(s, "setup");
        address caller = reverterFail % 2 == 0 ? actor : address(reverter);
        uint256 balBefore = address(c).balance;
        uint256 callerBalBefore = c.balances(caller);
        bool success;
        if (caller == actor) {
            vm.prank(actor);
            try c.withdraw() { success = true; } catch { success = false; }
        } else {
            vm.prank(address(reverter));
            try c.withdraw() { success = false; } catch { success = false; }
        }
        uint256 balAfter = address(c).balance;
        uint256 callerBalAfter = c.balances(caller);
        assertTrue(success ? (callerBalAfter == 0 && balBefore - balAfter == callerBalBefore) : (callerBalAfter == callerBalBefore && balAfter == balBefore));
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
